async (page) => {
  const { execSync } = require('child_process');

  try {
    // Get network interface information using ifconfig or ip command
    let output = '';

    try {
      // Try using 'ip' command first (more modern)
      output = execSync('ip addr show', { encoding: 'utf-8' });
    } catch (e) {
      // Fallback to ifconfig if ip command is not available
      output = execSync('ifconfig', { encoding: 'utf-8' });
    }

    return output;
  } catch (error) {
    return `Error: ${error.message}`;
  }
}
